// One set of evidence-backed priorities is used by the screen and AIOS export.
const conversionReports=new Map(),queryReports=new Map();let queryToken=0;
function sitePriorities(s){if(!payload)return [];const items=[],add=(rank,title,body,tab='growth',query=null)=>items.push({rank,title,body,tab,query});
 if(s.sessions==null||s.search==null)add(100,'Restore reporting access','One or more Google sources are unavailable. Missing reports cannot establish a decline.','health');
 const lost=(s.priorSearch?.clicks??0)-(s.clicks??0);if(s.clicks!=null&&s.priorSearch?.clicks>=10&&lost>=5&&change(s.clicks,s.priorSearch.clicks)<=-20)add(90,'Review lost search clicks',`${number(lost)} fewer clicks (${change(s.clicks,s.priorSearch.clicks).toFixed(1)}%) versus ${comparisonLabel()}. Compare search gains and losses before changing a page.`);
 if(s.sessions!=null&&s.priorSessions>=100&&s.priorSessions-s.sessions>=50&&change(s.sessions,s.priorSessions)<=-30)add(85,'Review lower website traffic',`${number(s.priorSessions-s.sessions)} fewer sessions. Review channel changes and the testing-page filter.`);
 if(s.events!=null&&s.sessions>=10&&!trackingStatus(s).connected)add(80,'Verify accepted-submission tracking','No accepted form events were recorded this period. This does not prove there were no inquiries or that tracking is broken. Verify delivery with the next real inquiry.','business');
 const errors=event(s,['form_submit_error','booking_error','form_error']);if(errors>0)add(95,'Review recorded form errors',`${number(errors)} error events were recorded. Check the form and delivery logs; these are events, not affected people.`,'business');
 const o=s.opportunities?.find(x=>x.impressions>=100&&x.ctr<.01)||s.opportunities?.[0];if(o)add(70,'Explore a search opportunity',`“${o.name}”: ${number(o.impressions)} impressions, ${pct(o.ctr)} CTR, average position ${o.position.toFixed(1)}. Open its exact query report to identify associated pages.`,'growth',o.name);
 const h=healthChecks.get(s.domain);if(h?.pages?.some(p=>p.reachable===false))add(98,'Review an unreachable page','The latest page check returned an unsuccessful HTTP result. Open Website health for the checked URL and timestamp.','health');
 if(s.domain===sites[0].domain&&payload.business?.followup?.status==='connected'){const c=payload.business.followup.counts;if(c.contact+c.prospectOverdue+c.guestOverdue>0)add(92,'Review the follow-up queue',`${number(c.contact)} inquiries await initial contact; ${number(c.prospectOverdue+c.guestOverdue)} follow-ups are overdue. Queues may overlap.`,'followup');}
 return items.sort((a,b)=>b.rank-a.rank).slice(0,3);
}
function sourceState(s,key){const analytics=key==='ga4',available=analytics?s.sessions!=null:s.search!=null,source=s.sources?.[key];const retrievedAt=source?.retrievedAt||payload?.updatedAt||null,stale=retrievedAt&&Date.now()-Date.parse(retrievedAt)>86400000;const records=analytics?s.trend:s.searchTrend,latestActivity=(records||[]).filter(p=>analytics?p.sessions>0:p.impressions>0||p.clicks>0).map(p=>p.date).sort().at(-1)||null;return {status:!available?'unavailable':stale?'refresh_needed':'available',retrievedAt,completedThrough:available?payload?.end:null,latestRecordedActivity:latestActivity,googleInternalUpdateTime:null};}
function freshnessPanel(s){const ga=sourceState(s,'ga4'),sc=sourceState(s,'gsc'),warning=[ga,sc].some(x=>x.status!=='available');return `<details class="source-freshness" ${warning?'open':''}><summary>Data freshness · ${warning?'source needs review':'GA4 & Search Console available'}</summary><div class="detailgrid">${[['GA4',ga],['Search Console',sc]].map(([label,x])=>`<article><h3>${label}</h3><p><span class="badge ${x.status==='available'?'green':'amber'}">${x.status==='available'?'Report available':x.status==='refresh_needed'?'Refresh needed':'Unavailable'}</span></p><p>Completed reporting dates through: ${escape(x.completedThrough||'—')}</p><p>Report retrieved: ${x.retrievedAt?escape(new Date(x.retrievedAt).toLocaleString()):'—'}</p><p>Latest recorded activity in the chart: ${escape(x.latestRecordedActivity||'None recorded / unavailable')}</p></article>`).join('')}</div><p class="muted">Retrieval time is when this reporting batch was fetched, not Google’s internal update time. Quiet days can be valid zero activity; they do not establish that tracking has stopped. Missing sources remain unavailable. Reporting ends three days ago.</p></details>`;}
function conversionPanel(s){const state=conversionReports.get(s.domain),data=state?.data,group=['forms','contacts'];return `<section class="conversion-panel"><div class="panelhead"><div><h3>90-day conversion activity</h3><p class="muted">Accepted forms and contact clicks beside your traffic trends.</p></div><button data-load-conversions ${state?.loading?'disabled':''}>${state?.loading?'Loading…':data?'Refresh conversion trends':'Load conversion trends'}</button></div>${state?.error?`<p role="alert">${escape(state.error)}</p>`:''}${data?`<div class="detailgrid">${group.map(key=>`<article><h3>${key==='forms'?'Accepted form events':'Contact click events'}</h3>${trend({...s,conversionTrend:data.conversionTrend},key)}</article>`).join('')}</div><p class="muted">${number(data.phoneClicks)} phone · ${number(data.emailClicks)} email · ${number(data.whatsappClicks)} WhatsApp clicks across the 90-day window. Contact clicks combine these event counts; they are not unique people or confirmed inquiries. Forms use the verified accepted-submission event names. Zero events do not verify tracking. No patient or customer records are included.</p>`:'<p class="muted">Loaded on demand from Google. Period-level form totals are not substituted for daily activity.</p>'}</section>`;}
function siteUpgrades(s){const items=sitePriorities(s);return freshnessPanel(s)+`<section class="site-attention"><div class="panelhead"><h3>What needs attention</h3><button class="report-export" data-export-report ${payload?'':'disabled'}>Download AIOS report ↓</button></div>${payload?`<div class="attentiongrid">${(items.length?items:[{title:'No large changes meet the review thresholds',body:'Review smaller movements in Growth and verify outcomes as the website develops.'}]).map(a=>`<article class="attentioncard"><h3>${escape(a.title)}</h3><p>${escape(a.body)}</p>${a.query?`<button data-query="${escape(a.query)}">Explore query →</button>`:a.tab?`<a class="rowlink" data-route href="${siteUrl(s.domain,a.tab)}">Review ${escape(tabs.find(t=>t[0]===a.tab)?.[1])} →</a>`:''}</article>`).join('')}</div>`:'<p class="muted">Waiting for reports.</p>'}<p class="muted">Review suggestions from the selected period; not automatic diagnoses.</p></section>`+(selectedTab==='growth'||selectedTab==='business'?conversionPanel(s):'');}
async function loadConversions(){if(!payload)return;const domain=selectedDomain,id=requestId;conversionReports.set(domain,{loading:true});render();try{const q=new URLSearchParams({site:domain,conversions:'1',days:document.getElementById('days').value});if(document.getElementById('include-tests').checked)q.set('tests','include');const r=await fetch('/api/portfolio?'+q,{cache:'no-store'}),p=await r.json(),s=p.sites?.find(s=>s.domain===domain);if(!r.ok||!p.ok||!p.conversions||p.end!==payload?.end||!Array.isArray(s?.conversionTrend))throw Error(p.error||'Daily conversion reporting is not connected yet. No estimated trend is displayed.');if(id!==requestId)return;conversionReports.set(domain,{data:s,updatedAt:p.updatedAt});}catch(e){if(id!==requestId)return;conversionReports.set(domain,{error:e.message});}render();}
const queryDialog=document.createElement('dialog');queryDialog.id='query-dialog';queryDialog.setAttribute('aria-labelledby','query-title');document.body.append(queryDialog);queryDialog.addEventListener('close',()=>queryToken++);
function queryShell(query,body){queryDialog.innerHTML=`<header class="panelhead"><h2 id="query-title">${escape(query)} · search report</h2><form method="dialog"><button aria-label="Close query report">Close ×</button></form></header>${body}`;}
function queryPlot(rows,key){if(!Array.isArray(rows))return '<p class="muted">Trend unavailable.</p>';const byDate=new Map(rows.map(r=>[r.date,r])),points=[];for(let t=Date.parse(payload.trendStart+'T00:00:00Z');t<=Date.parse(payload.end+'T00:00:00Z');t+=86400000){const date=new Date(t).toISOString().slice(0,10),r=byDate.get(date);points.push({date,value:r?.[key]??null});}const observed=points.filter(p=>p.value!=null);if(!observed.length)return '<p class="muted">No query rows returned for this window. Omitted query rows remain gaps.</p>';const max=Math.max(1,...observed.map(p=>p.value)),x=i=>220*i/Math.max(1,points.length-1);let path='',connected=false;points.forEach((p,i)=>{if(p.value==null){connected=false;return;}path+=(connected?'L':'M')+x(i).toFixed(1)+','+(48-p.value/max*44).toFixed(1)+' ';connected=true;});const ticks=[0,Math.round((points.length-1)/2),points.length-1];return `<div class="query-series" data-query-series="${escape(JSON.stringify(points))}" data-query-key="${key}"><h3>${key==='position'?'Average ranking position · lower is better':'Daily impressions'}</h3><svg viewBox="0 0 220 76" tabindex="0" role="slider" aria-label="${key} by date. Use arrow keys." aria-valuemin="0" aria-valuemax="${points.length-1}" aria-valuenow="${points.length-1}" aria-valuetext="${points.at(-1).date}"><path d="M0 49H220" stroke="#d5dfcc"/><path d="${path}" fill="none" stroke="${key==='position'?'#0d5925':'#835b15'}" stroke-width="2"/><g fill="#53634e" font-size="7">${ticks.map((i,j)=>`<text x="${x(i)}" y="65" text-anchor="${j===0?'start':j===2?'end':'middle'}">${points[i].date.slice(5)}</text>`).join('')}<text x="0" y="9">${max.toFixed(key==='position'?1:0)}</text></g></svg><p class="series-readout muted" aria-live="polite">Hover, tap or use arrow keys for the date and value.</p></div>`;}
async function openQuery(query){if(!payload||!selectedDomain)return;const domain=selectedDomain,id=requestId,token=++queryToken,key=[id,domain,query].join('|');queryShell(query,'<p role="status">Loading exact-query Google reports…</p>');if(!queryDialog.open)queryDialog.showModal();try{let p=queryReports.get(key);if(!p){const q=new URLSearchParams({site:domain,query,days:document.getElementById('days').value,compare:document.getElementById('comparison').value});const r=await fetch('/api/portfolio?'+q,{cache:'no-store'});p=await r.json();if(!r.ok||!p.ok||!p.queryReport||p.query!==query||p.start!==payload?.start||p.end!==payload?.end||!p.sites?.some(s=>s.domain===domain))throw Error(p.error||'Exact-query reporting is not connected yet. No guessed page associations are displayed.');queryReports.set(key,p);}if(token!==queryToken||id!==requestId||!queryDialog.open)return;const s=p.sites.find(s=>s.domain===domain);queryShell(query,`<p class="muted">${escape(p.start)} → ${escape(p.end)} · comparison ${escape(p.priorStart)} → ${escape(p.priorEnd)}.</p><div class="detailstats">${[['Clicks','clicks'],['Impressions','impressions'],['Average position','position']].map(([label,k])=>`<div><span class="eyebrow">${label}</span><strong>${number(s.queryTotals?.[k])}</strong><small>Comparison: ${number(s.priorQueryTotals?.[k])}</small></div>`).join('')}</div><h3>Pages Google associates with this exact query</h3>${searchTable(s.queryPages,true)}<div class="detailgrid"><article>${queryPlot(s.queryTrend,'impressions')}</article><article>${queryPlot(s.queryTrend,'position')}</article></div><p class="muted">Google can anonymize or omit query rows. Missing dates are gaps, not zero. Average position mixes impressions across pages, devices and countries; it is not a fixed rank. These associations do not establish which page should be edited or what caused a change.</p><p class="muted">Report retrieved ${escape(new Date(p.updatedAt).toLocaleString())}.</p>`);}catch(e){if(token===queryToken&&id===requestId&&queryDialog.open)queryShell(query,`<p role="alert">${escape(e.message)}</p>`);}}
function showQueryPoint(el,index){const ps=JSON.parse(el.dataset.querySeries),i=Math.max(0,Math.min(ps.length-1,index)),p=ps[i],text=p.date+' · '+(p.value==null?'No query row returned':el.dataset.queryKey+': '+number(p.value));el.querySelector('.series-readout').textContent=text;const svg=el.querySelector('svg');svg.setAttribute('aria-valuenow',i);svg.setAttribute('aria-valuetext',text);}
document.addEventListener('pointermove',e=>{const el=e.target.closest('.query-series');if(!el||!e.target.closest('svg'))return;const svg=el.querySelector('svg'),m=svg.getScreenCTM();if(m)showQueryPoint(el,Math.round(new DOMPoint(e.clientX,e.clientY).matrixTransform(m.inverse()).x/220*(JSON.parse(el.dataset.querySeries).length-1)));});
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.query-series');if(!el||!e.target.closest('svg'))return;const m=el.querySelector('svg').getScreenCTM();if(m)showQueryPoint(el,Math.round(new DOMPoint(e.clientX,e.clientY).matrixTransform(m.inverse()).x/220*(JSON.parse(el.dataset.querySeries).length-1)));});
document.addEventListener('keydown',e=>{const el=e.target.closest('.query-series');if(!el||!['Home','End','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const count=JSON.parse(el.dataset.querySeries).length,i=Number(el.querySelector('svg').getAttribute('aria-valuenow'));showQueryPoint(el,e.key==='Home'?0:e.key==='End'?count-1:i+(e.key==='ArrowRight'?1:-1));});
function aiosReport(){return {schema:'portfolio-aios-report',version:1,generatedAt:new Date().toISOString(),period:{start:payload.start,end:payload.end,priorStart:payload.priorStart,priorEnd:payload.priorEnd,comparison:payload.comparison,trendStart:payload.trendStart,includeTests:payload.includeTests},definitions:{forms:'Accepted-submission events, not unique people or qualified leads',contactClicks:'Phone/email/WhatsApp event counts, not confirmed inquiries',freshness:'Report retrieval timestamps are not Google internal update times',missing:'null or unavailable is not zero',causation:'Change dates and trends provide context, not proof of causation',privacy:'Aggregate website and business counts only; no customer or patient details',scope:'Current dashboard snapshot; sources not loaded or not connected remain unavailable'},sites:sites.map(s=>({name:s.name,domain:s.domain,stage:s.stage,reportUrl:new URL(siteUrl(s.domain),'https://admin.mindobirdwatching.com').href,sources:{ga4:sourceState(s,'ga4'),gsc:sourceState(s,'gsc')},priorities:sitePriorities(s),metrics:{sessions:s.sessions??null,priorSessions:s.priorSessions??null,search:s.search??null,priorSearch:s.priorSearch??null,forms:forms(s),events:s.events??null},trafficTrend:s.trend??null,searchTrend:s.searchTrend??null,channels:s.channels??null,pages:s.pages??null,opportunities:s.opportunities??null,queries:s.queries??null,searchPages:s.searchPages??null,detailStatus:detailState.get(s.domain)||'not_loaded',landingPages:s.landingPages??null,referrers:s.referrers??null,conversionReport:conversionReports.get(s.domain)||{status:'not_loaded'},health:healthChecks.get(s.domain)||{status:'not_checked'},mobile:mobileChecks.get(s.domain)||{status:'not_checked'},goal:goalsReady?goalRows.find(g=>g.domain===s.domain)||null:{status:'unavailable'},confirmedTracking:trackingReady?trackingDates.find(t=>t.domain===s.domain)||null:{status:'unavailable'}})),business:payload.business??{status:'unavailable'},changes:changeLogReady?changeEntries:{status:'unavailable'},queryReports:[...queryReports.values()],readInstructions:'Read all sites, prioritize failures and business outcomes, disclose missing sources and reporting windows, never infer diagnoses, patient information, earned revenue, unique inquiries or causation from event counts.'};}
function exportAios(){if(!payload)return;const blob=new Blob([JSON.stringify(aiosReport(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='portfolio-aios-'+payload.end+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{if(e.target.closest('[data-load-conversions]'))return loadConversions();if(e.target.closest('[data-export-report]'))return exportAios();const q=e.target.closest('[data-query]');if(q&&q.closest('#micro'))openQuery(q.dataset.query);});
const resetBeforeUpgrades=reset;reset=()=>{conversionReports.clear();queryReports.clear();queryToken++;if(queryDialog.open)queryDialog.close();resetBeforeUpgrades();};
const renderBeforeUpgrades=render;render=()=>{renderBeforeUpgrades();if(!selectedDomain){const head=document.querySelector('#performance').closest('.panelhead');if(!head.querySelector('[data-export-report]'))head.insertAdjacentHTML('beforeend',`<button class="report-export" data-export-report ${payload?'':'disabled'}>Download AIOS report ↓</button>`);else head.querySelector('[data-export-report]').disabled=!payload;}};
render();
